21	// TestRevokeSessionExpiresDuePendingWithoutQuery：申请已到等待截止时刻但
22	// 从未被查询过，吊销时必须按其原有截止时间进入过期终态，而不是吊销拒绝。
23	func TestRevokeSessionExpiresDuePendingWithoutQuery(t *testing.T) {
24		w, c := setupApproval(t)
25		req, err := w.Apply(approvalApply())
26		if err != nil {
27			t.Fatal(err)
28		}
29		deadline := req.WaitDeadline
30		createdAt := req.CreatedAt
31		before := len(w.Ledger())
32	
33		// 直接越过等待截止时刻，中途不查询这笔申请。
34		c.t = deadline.Add(time.Second)
35		revokeAt := c.t
36		if err := w.RevokeSession("s1"); err != nil {
37			t.Fatal(err)
38		}
39	
40		got, err := w.Request("u1", "r1")
41		if err != nil {
42			t.Fatal(err)
43		}
44		if got.State != RequestExpired {
45			t.Fatalf("state = %v, want expired", got.State)
46		}
47		if got.RejectReason != "" {
48			t.Fatalf("expired by deadline must carry no revoke reason: %q", got.RejectReason)
49		}
50		if got.ApproverAccountID != "" {
51			t.Fatalf("expired request must not record approver: %q", got.ApproverAccountID)
52		}
53		if !got.DecidedAt.Equal(revokeAt) {
54			t.Fatalf("decided at %v, want revoke time %v", got.DecidedAt, revokeAt)
55		}
56		// 提交时间与等待截止时间保持不变。
57		if !got.CreatedAt.Equal(createdAt) || !got.WaitDeadline.Equal(deadline) {
58			t.Fatalf("timing changed: created %v/%v deadline %v/%v", got.CreatedAt, createdAt, got.WaitDeadline, deadline)
59		}
60	
61		// 账本：一条零金额过期留痕，没有拒绝记录。
62		all := w.Ledger()
63		if len(all) != before+1 {
64			t.Fatalf("ledger entries = %d, want %d", len(all), before+1)
65		}
66		e, ok := ledgerEntryFor(all, LedgerExpiration, "r1")
67		if !ok {
68			t.Fatal("missing LedgerExpiration entry")
69		}
70		if e.AccountID != "u1" || e.Amount != 0 {
71			t.Fatalf("expiration entry = %+v", e)
72		}
73		if !e.At.Equal(revokeAt) {
74			t.Fatalf("ledger at %v, want processing (revoke) time %v", e.At, revokeAt)
75		}
76		if countKind(all, LedgerRejection) != 0 {
77			t.Fatal("due pending request must not be recorded as revocation rejection")
78		}
79	
80		// 待审批没有冻结费用：余额与策略累计均不变。
81		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
82			t.Fatalf("balance = %+v, want untouched", bal)
83		}
84		if pv, _ := w.Policy("p-approval"); pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
85			t.Fatalf("policy totals = reserved %d spent %d, want 0/0", pv.ReservedTotal, pv.SpentTotal)
86		}
87	}
